    assets_error_set(error, ASSETS_ERROR_NO_EMBEDDED_DATA, NULL,
                    "No embedded data available. Library was compiled without HAS_EMBEDDED_DATA");
    return ASSETS_ERROR_NO_EMBEDDED_DATA;
